def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opps = []
    prev_bids = []
    dangerous_bids = []
    rich_count = 0

    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opps.append(opp)
            if opp.get('budget', 0) >= DAILY_SALARY:
                rich_count += 1
            prev = opp.get('previous_trace', {}) or {}
            bid = prev.get('bid')
            if bid is not None:
                prev_bids.append(float(bid))
                if opp.get('budget', 0) > 0 and opp.get('hp', 0) > 1:
                    dangerous_bids.append(float(bid))

    if not alive_opps:
        return float(min(budget, DAILY_SALARY * 0.35))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    dangerous_prev = max(dangerous_bids) if dangerous_bids else highest_prev

    urgency = 0
    if hp <= 2:
        urgency += 3
    elif hp <= 4:
        urgency += 2
    elif hp <= 6:
        urgency += 1

    if no_water >= 2:
        urgency += 3
    elif no_water >= 1:
        urgency += 1

    if supply <= 17:
        urgency += 2
    elif supply <= 20:
        urgency += 1

    if rich_count >= 2:
        urgency += 1

    if urgency >= 6:
        target = max(DAILY_SALARY * 1.1, dangerous_prev + 3.0)
    elif urgency >= 4:
        target = max(DAILY_SALARY * 0.9, dangerous_prev + 2.0)
    elif urgency >= 2:
        target = max(DAILY_SALARY * 0.62, dangerous_prev + 1.0)
    else:
        if dangerous_prev >= DAILY_SALARY * 1.5:
            target = DAILY_SALARY * 0.28
        elif dangerous_prev >= DAILY_SALARY * 0.95:
            target = DAILY_SALARY * 0.4
        else:
            target = max(DAILY_SALARY * 0.34, dangerous_prev * 0.78)

    if day >= 8:
        target *= 1.08
    if day >= 9 and (hp <= 4 or no_water >= 1):
        target *= 1.15

    reserve_floor = 0.0
    days_left = max(0, 10 - day)
    if days_left >= 3 and hp > 3:
        reserve_floor = DAILY_SALARY * 0.35

    cap = max(0.0, budget - reserve_floor)
    if urgency >= 4:
        cap = budget

    bid = min(target, cap if cap > 0 else budget)

    if hp <= 1 or no_water >= 2:
        bid = min(budget, max(bid, DAILY_SALARY * 1.2, dangerous_prev + 4.0))

    if budget < DAILY_SALARY * 0.5:
        bid = min(budget, max(1.0, budget * 0.9))

    if bid < 0:
        bid = 0.0
    return float(min(budget, bid))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    hp = float(my_status.get('hp', 0.0))
    budget = float(my_status.get('budget', 0.0))
    no_water_days = int(my_status.get('no_water_days', 0))

    alive_opps = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opps.append(opp)

    if not alive_opps:
        cap = min(budget, DAILY_SALARY * 0.4)
        return max(0.0, cap)

    # Extract yesterday bids from immediate previous_trace
    yesterday_bids = []
    for opp in alive_opps:
        prev = opp.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                yesterday_bids.append(float(b))
            except Exception:
                pass

    highest_prev_bid = max(yesterday_bids) if yesterday_bids else 0.0

    # Supply pressure: higher supply reduces need to overbid
    # Normalize supply to [0,1] where 0 is MIN_SUPPLY, 1 is MAX_SUPPLY
    denom = (MAX_SUPPLY - MIN_SUPPLY)
    if denom <= 0:
        supply_norm = 0.5
    else:
        supply_norm = (supply - MIN_SUPPLY) / denom
        if supply_norm < 0.0:
            supply_norm = 0.0
        if supply_norm > 1.0:
            supply_norm = 1.0

    # Base bid: aim to secure enough water for our requirement without matching overbidders
    # If supply is tight (low norm), bid closer to salary; if abundant, bid closer to mid.
    base = DAILY_SALARY * (0.35 + 0.35 * (1.0 - supply_norm))

    # If we are in danger (low HP or accumulating no-water days), increase bid aggressiveness
    danger = 0.0
    if hp <= 2.0:
        danger += 1.0
    if no_water_days >= 2:
        danger += 0.6
    if hp <= 4.0:
        danger += 0.4

    # If opponents were bidding very high yesterday, they likely value survival strongly.
    # Underbid slightly when we're safe; overbid when we're in danger.
    high_opponent = 1.0 if highest_prev_bid >= DAILY_SALARY * 0.85 else 0.0

    if high_opponent > 0.5:
        if danger >= 1.0:
            target = DAILY_SALARY * 0.95
        else:
            # Slight undercut/near-match
            target = min(DAILY_SALARY * 0.75, highest_prev_bid * 0.98)
    else:
        target = base
        if danger >= 1.0:
            target = max(target, DAILY_SALARY * 0.8)

    # Final cap by budget and non-negative
    bid = min(budget, target)
    if bid < 0.0:
        bid = 0.0

    # If supply is extremely low, add a small bump to avoid being starved
    if supply <= (MIN_SUPPLY + 1.0):
        bid = min(budget, bid + DAILY_SALARY * 0.08)

    return float(bid)

